TYPE ST_Station_Data :
STRUCT
	// Comm. with other stations, main cycle
//Station Constant
	sStationName				:STRING;	
//Station Input from Main cycle
	bStation_Enabled			:BOOL;
	bResetERROR					:BOOL;
	bErrorStringConfirmed		:BOOL;
	bWarningStringConfirmed		:BOOL;

//Station Output to Main cycle
	bStation_In_Basic_Pos		:BOOL;
	bStation_ERROR				:BOOL;	
	bStation_WARNING			:BOOL;	
	sStation_ERROR				:STRING[250];
	iERRORLevel					:USINT;
	sStation_WARNING			:STRING[250];
	iOEECategoryNumber			:INT;	(*OEE Kategória MES adatbázisnak*)
	bCycle_End_finished			:BOOL;
	bStation_Busy				:BOOL;	// Signal for ECO mode
	arr_bStation_OutComm				:ARRAY[0..20] OF BOOL;			// Out going communication, One signal for each nest
	arr_sStation_OutCommString			:ARRAY[0..20] OF STRING;		// to explain wich signal comuunicates to where
	arr_sStation_OutCommToolTip			:ARRAY[0..20] OF STRING (120);	// to ad aditional info to the user on the HMI
	arr_bStation_InComm					:ARRAY[0..20] OF BOOL;			// Incomming communication, One signal for each nest
	arr_sStation_InCommString			:ARRAY[0..20] OF STRING;		// to explain wich signal comuunicates to where
	arr_sStation_InCommToolTip			:ARRAY[0..20] OF STRING (120);	// to ad aditional info to the user on the HMI
//For internal use, within the FB

// max. 6 Step chain / station
	arr_bStepModeActive			:ARRAY[0..5] OF BOOL;
	arr_bStepOver				:ARRAY[0..5] OF BOOL;
	arr_iStep					:ARRAY[0..5] OF UINT;
	arr_StepStatus				:ARRAY[0..5] OF STRING (255);
	// StepTimeOut
	arr_bSemafor				:ARRAY[0..5] OF BOOL;
	arr_Exceptions				:ARRAY[0..5] OF ST_StepTimeoutExceptions;
	arr_bStepTimeOutERROR		:ARRAY[0..5] OF BOOL;
	arr_sStepTimeOutERROR		:ARRAY[0..5] OF STRING[255];

	arr_Step_Archive_0			:ARRAY[0..40] OF UINT;
	arr_Step_Archive_1			:ARRAY[0..40] OF UINT;
	arr_Step_Archive_2			:ARRAY[0..40] OF UINT;
	arr_Step_Archive_3			:ARRAY[0..40] OF UINT;
	arr_Step_Archive_4			:ARRAY[0..40] OF UINT;

	arr_StepState_Archive_0			:ARRAY[0..40] OF STRING(255);
	arr_StepState_Archive_1			:ARRAY[0..40] OF STRING(255);
	arr_StepState_Archive_2			:ARRAY[0..40] OF STRING(255);
	arr_StepState_Archive_3			:ARRAY[0..40] OF STRING(255);
	arr_StepState_Archive_4			:ARRAY[0..40] OF STRING(255);

	arr_Sequence_in_Basic_Position	:ARRAY[0..5] OF BOOL;
END_STRUCT
END_TYPE

TYPE ST_ERROR_Handling :
STRUCT
	sDatAndTime			:STRING;
	sERRORMessage		:STRING(255);
END_STRUCT
END_TYPE

