tonStationEnableDelay(IN:=NOT bFirstCompleteCycleOffPLC , PT:=T#30S , Q=> , ET=> );
rtrigTONStationDelay(CLK:=tonStationEnableDelay.Q , Q=> );

	IF rtrigTONStationDelay.Q THEN												// HMI induláskor kilövi 0-ba, hiába van bebillentve az első PLC ciklusnál
		arr_StationData[iStationNumber].bStation_Enabled:=TRUE;					// Ezért van timer-ezve
	END_IF;

	iStationNumber:=0;  // Lokális állomás, a lokális változót használja
	arr_StationData[iStationNumber].sStationName:=FC_Locale('','Mérleg','scale');

(*	// Hiba és Warning üzenetek átadása a fő PLC ciklusnak
	bERROR:=arr_StationData[iStationNumber].bStation_ERROR;
	sERROR:=arr_StationData[iStationNumber].sStation_ERROR;
	bWarning:=arr_StationData[iStationNumber].bStation_WARNING;
	sWarning:=arr_StationData[iStationNumber].sStation_WARNING;

	arr_StationData[iStationNumber].arr_bStation_OutComm[0];
	arr_StationData[iStationNumber].arr_sStation_OutCommString[0]:='Mérleg not busy, pohár a helyén van!';
	arr_StationData[iStationNumber].arr_sStation_OutCommToolTip[0]:='Jelzés a szervónak hogy a mérleg készen áll,pohár a helyén van!';



	arr_StationData[iStationNumber].arr_bStation_InComm[0];
	arr_StationData[iStationNumber].arr_sStation_InCommString[0]:='Külső kérés mérleg tárázásra';
	arr_StationData[iStationNumber].arr_sStation_InCommToolTip[0]:='Külső kérés mérleg tárázásra';
*)

fb_StationERROR(arrsErrorString:=arrsErrorString ,
						arrbError:=arrbError ,
						 bEnable:=arr_StationData[iStationNumber].bStation_Enabled,
						iStationNumber:=iStationNumber,
						arrOEEErrorCode:=arrOEEErrorCode,
						sStationERROR=>arr_StationData[iStationNumber].sStation_ERROR,);
(*// Set array		
// EL6001 Failure
arrsErrorString[0]:=TO_STRING(enum_EL6001CtrlErrorID);
arrbError[0]:=bEL6001CtrlError;
arrOEEErrorCode[0]:=2136;

// Step timeout ERROR	
arrsErrorString[14]:=arr_StationData[iStationNumber].arr_sStepTimeOutERROR[0];
arrbError[14]:= arr_StationData[iStationNumber].arr_bStepTimeOutERROR[0]; 
arrOEEErrorCode[14]:=2136;

arrsErrorString[15];		// Step sequence ERROR
arrbError[15];
arrOEEErrorCode[15];

IF bGlobalResetERROR THEN
	i:=0;
	FOR i:=0 TO 20 DO
		arrbError[i]:=FALSE;
		arrsErrorString[i]:='';
	END_FOR 	

END_IF
*)

// Warning Handling
FB_Warning_Handling_For_Stations(arrsWarningString:=arrsWarningString ,
	 						bEnable:=arr_StationData[iStationNumber].bStation_Enabled,
							 arrbWarning:=arrbWarning ,
							 iStationNumber:=iStationNumber ,
							 sStationWarning=> );

arrbWarning[0];	// Step sequence warning 
arrsWarningString[0];

arrbWarning[15];	// Step sequence warning
arrsWarningString[15];

// Reset Warning messages
// Reset Warning messages

IF bGlobalResetWARNING THEN
	i:=0;
	FOR i:=0 TO 20 DO
		arrbWarning[i]:=FALSE;
		arrsWarningString[i]:='';
	END_FOR 	

END_IF

//Station is not enabled
IF NOT arr_StationData[iStationNumber].bStation_Enabled  THEN
	arr_StationData[iStationNumber].bStation_In_Basic_Pos:=FALSE;
	arr_StationData[iStationNumber].bStation_ERROR:=FALSE;
	arr_StationData[iStationNumber].sStation_ERROR:='';

	arr_StationData[iStationNumber].bStation_WARNING:=FALSE;
	arr_StationData[iStationNumber].sStation_WARNING:='';

	arr_StationData[iStationNumber].bCycle_End_finished:=FALSE;
	arr_StationData[iStationNumber].bStation_Busy:=FALSE;
	arr_StationData[iStationNumber].bStation_Busy:=FALSE;

	i:=0;
		FOR i:=0 TO 20 DO
			arr_StationData[iStationNumber].arr_bSemafor[i]:=FALSE;
			arr_StationData[iStationNumber].arr_bStation_OutComm[i]:=FALSE;
			arr_StationData[iStationNumber].arr_bStation_InComm[i]:=FALSE;
			arr_StationData[iStationNumber].arr_bStepModeActive[i]:=FALSE;
			arr_StationData[iStationNumber].arr_bStepOver[i]:=FALSE;
			arr_StationData[iStationNumber].arr_bStepTimeOutERROR[i]:=FALSE;
			arr_StationData[iStationNumber].arr_sStepTimeOutERROR[i]:='';
			arr_StationData[iStationNumber].arr_StepStatus[i]:='';
		END_FOR 

	arr_StationData[iStationNumber].stPartStatus:=0;	
	arr_StationData[iStationNumber].arr_iStep[0]:=0;
	arr_bNoPartAtInput[1]:=FALSE;
END_IF

(*(******************************************************************* Step sequence archive*)
IF bClr THEN
	arr_StationData[iStationNumber].arr_Step_Archive_0:=arrClr_Step_Archive;
	bClr:=FALSE;
END_IF

IF arr_StationData[iStationNumber].arr_Step_Archive_0[0] <> arr_StationData[iStationNumber].arr_iStep[0] THEN
	FOR i:=40 TO 0 DO
		arr_StationData[iStationNumber].arr_Step_Archive_0[i]:= arr_StationData[iStationNumber].arr_Step_Archive_0[i-1];
	END_FOR
	arr_StationData[iStationNumber].arr_Step_Archive_0[0]:= arr_StationData[iStationNumber].arr_iStep[0];
END_IF

arr_StationData[iStationNumber].arr_Step_Archive_0[0];
arr_StationData[iStationNumber].arr_Step_Archive_0[1];
arr_StationData[iStationNumber].arr_Step_Archive_0[2];
arr_StationData[iStationNumber].arr_Step_Archive_0[3];
arr_StationData[iStationNumber].arr_Step_Archive_0[4];
arr_StationData[iStationNumber].arr_Step_Archive_0[5];
