arr_StationData[iStationNumber].arr_Step_Archive_0[15];
arr_StationData[iStationNumber].arr_Step_Archive_0[16];
arr_StationData[iStationNumber].arr_Step_Archive_0[17];
arr_StationData[iStationNumber].arr_Step_Archive_0[18];
arr_StationData[iStationNumber].arr_Step_Archive_0[19];
arr_StationData[iStationNumber].arr_Step_Archive_0[20];

// Step chain semafor
fb_StepChainSemafor_STepChain0(
	iStationNumber:=iStationNumber, 
	iStepChainNumber:=0 , 
	tStepOverTime:=T#10MS , 
	bBypass_Automatic:=TRUE);

//Step timeout exceptions
arr_StationData[iStationNumber].arr_Exceptions[0].arrExceptions[0]:=0;
arr_StationData[iStationNumber].arr_Exceptions[0].arrExceptions[1]:=10;
arr_StationData[iStationNumber].arr_Exceptions[0].arrExceptions[2]:=1000;
arr_StationData[iStationNumber].arr_Exceptions[0].arrExceptions[3]:=1010;
arr_StationData[iStationNumber].arr_Exceptions[0].arrExceptions[4]:=10000;
arr_StationData[iStationNumber].arr_Exceptions[0].arrExceptions[5]:=25;
arr_StationData[iStationNumber].arr_Exceptions[0].arrExceptions[6]:=0;
arr_StationData[iStationNumber].arr_Exceptions[0].arrExceptions[7]:=0;	
arr_StationData[iStationNumber].arr_Exceptions[0].arrExceptions[8]:=0;
arr_StationData[iStationNumber].arr_Exceptions[0].arrExceptions[9]:=0;
arr_StationData[iStationNumber].arr_Exceptions[0].arrExceptions[10]:=0;
arr_StationData[iStationNumber].arr_Exceptions[0].arrExceptions[11]:=0;

// Step timeout
fb_StepTimeOut_STepChain0(
	iStationNumber:=iStationNumber , 
	iStepChainNumber:=0 , 
	tTimeOut:=T#20S , 
	bEnable:= NOT arr_StationData[iStationNumber].arr_bStepModeActive[0] );

// Reset Step Cycle controll if station is in error and a reset error comes
IF (arr_StationData[iStationNumber].bStation_ERROR 
	AND arr_StationData[iStationNumber].arr_iStep[0]<> 10000)
	OR br_trig_BaseMoveActive THEN 
		bStationWasInERROR:=TRUE;
END_IF

IF bStationWasInERROR
	AND NOT arr_StationData[iStationNumber].bStation_ERROR THEN  //Nyugtázták a hibát
	 	arr_StationData[iStationNumber].arr_iStep[0]:=0;
		bStationWasInERROR:=FALSE;	 
END_IF;

// Step Sequence
CASE arr_StationData[iStationNumber].arr_iStep[0] OF
	0:arr_StationData[iStationNumber].arr_StepStatus[0]:='Várakozás állomás engedélyezésre!';

	sReceivedString:='';
	sLastReceivedString:='';
	bStringReceivedArchive:=FALSE;

	IF arr_StationData[iStationNumber].bStation_Enabled  THEN
		arr_StationData[iStationNumber].arr_iStep[0]:=arr_StationData[iStationNumber].arr_iStep[0]+10;
	END_IF

	10:arr_StationData[iStationNumber].arr_StepStatus[0]:='Várakozás alaphelyzet felvétel kérésre!';

		arr_StationData[iStationNumber].bStation_In_Basic_Pos:=FALSE;

		arr_StationData[iStationNumber].arr_bStation_OutComm[0]:=FALSE; // Mérleg készen áll, pohár a helyén!		
		arr_StationData[iStationNumber].arr_bStation_OutComm[1]:=FALSE; // Mérleg végzett a tárázással!
		arr_StationData[iStationNumber].arr_bStation_OutComm[2]:=FALSE; // Mérleg végzett a súlyméréssel		

	IF bBaseMoveActive
		AND NOT arr_StationData[iStationNumber].arr_bSemafor[0] THEN
			arr_StationData[iStationNumber].arr_iStep[0]:=arr_StationData[iStationNumber].arr_iStep[0]+10;;
	END_IF



	10000:	arr_StationData[iStationNumber].arr_StepStatus[0]:='Lépéslánc hiba!';

		arrbError[15]:=TRUE;

		IF bGlobalResetERROR THEN
			arrbError[15]:=FALSE;
			arrsErrorString[15]:='';
			arr_StationData[iStationNumber].arr_iStep[0]:=0;	
			arrOEEErrorCode[15]:=0;
			bStationWasInERROR:=FALSE;
		END_IF

	10100:	arr_StationData[iStationNumber].arr_StepStatus[0]:='Figyelmeztetés aktív!';

		arrbWarning[15]:=TRUE;

		IF bGlobalResetWARNING THEN
			arrbWarning[15]:=FALSE;
			arrsWarningString[15]:='';
			arr_StationData[iStationNumber].arr_iStep[0]:=1000;		
		END_IF
END_CASE
*)

// Action calls
A_Init();
B_Constants();
C_FB_Calls();
D_ERROR_Handling();
E_Timers_Edge_Detection();
F_Enable_Signal_Handling();
G_Step_Sequence();
H_Others();
I_Outputs();

