		arrOEEErrorCode			:ARRAY[0..40]OF INT;
		iStationNumber			:UINT;
END_VAR
VAR_OUTPUT
		sStationERROR				:STRING[255];
		arrbErrorStringConfirmed	:ARRAY[0..40]OF BOOL;
END_VAR

VAR
	i							: INT;
	iAmountOfERROR				: INT;
	arrsErrorStringArchive		: ARRAY[0..40]OF STRING[255];
	arrsCLRErrorStringArchive	: ARRAY[0..40]OF STRING[255];
