arrsErrorString[40];

// Timers
tofWaitAfterResetERROR(IN:= , PT:=T#500MS , Q=> , ET=> );
tofWaitAfterResetERROR.ET;

IF bEnable THEN
	// Get ERROR bit from every device within the station
	IF NOT tofWaitAfterResetERROR.Q THEN							// Wait x ms after reset error, to give time to stations to reset their error
		IF NOT  arr_StationData[iStationNumber].bStation_ERROR THEN
			FOR i:=0 TO 40 BY 1 DO
				IF arrbError[i] = TRUE THEN
					iAmountOfERROR:=iAmountOfERROR+1;
					IF iAmountOfERROR > 100 THEN
						iAmountOfERROR:=100;
					END_IF
				END_IF
			END_FOR
		END_IF
	ELSE
		tofWaitAfterResetERROR.IN:=FALSE;
	END_IF
	// Set Station ERROR Bit
	IF iAmountOfERROR > 0 THEN
		 arr_StationData[iStationNumber].bStation_ERROR:=TRUE;
	END_IF

	// Reset ERROR
	r_TrigResetERROR(CLK:=bGlobalResetERROR , Q=> );

	IF r_TrigResetERROR.Q THEN
		iAmountOfERROR:=0;
		arr_StationData[iStationNumber].bStation_ERROR:=FALSE;
		arr_StationData[iStationNumber].sStation_ERROR:='';
		sStationERROR:='';
		arrsErrorStringArchive:=arrsCLRErrorStringArchive;
		iStepNumber:=0;
		tofWaitAfterResetERROR.IN:=TRUE;	
	END_IF

	IF  arr_StationData[iStationNumber].bStation_ERROR THEN
			// ERROR String handling
			CASE iStepNumber OF 
				0:// Chek if there is a new ERROR String
				FOR i:=0 TO 40 DO
					IF arrsErrorString[i] <> arrsErrorStringArchive[i] 
						AND arrsErrorString[i]<> '' 
						AND arrbError[i] = TRUE THEN // csak azt a stringet teszi ki amelyik adja a hiba bitet
						 arrsErrorStringArchive[i]:= arrsErrorString[i];
						 arr_StationData[iStationNumber].sStation_ERROR:=FUN_Build_String_5(arr_StationData[iStationNumber].sStationName,'  :',arrsErrorString[i],'ERROR Level: ',INT_TO_STRING(arrERRORLevel[i]));
						 arr_StationData[iStationNumber].iERRORLevel:=arrERRORLevel[i];
						 arr_StationData[iStationNumber].iOEECategoryNumber:=arrOEEErrorCode[i];
						 sStationERROR:=CONCAT( arr_StationData[iStationNumber].sStationName,Concat('  :',arrsErrorString[i]));
						 iStepNumber:=10;
						 EXIT;
					END_IF
				END_FOR
				10:// Wait for ERROR String confirmation from MAIN cycle

				IF arr_StationData[iStationNumber].bErrorStringConfirmed THEN			// Megvárja amíg a main ciklus kiírja a hibát, és csak utánna rak ki újat
					arr_StationData[iStationNumber].bErrorStringConfirmed:=FALSE;
					arrbErrorStringConfirmed[i]:=TRUE;
					arr_StationData[iStationNumber].sStation_ERROR:='';
					iStepNumber:=20;
				END_IF
				20:// Reset Error confirmation signal

				FOR i:=0 TO 20 DO
					arrbErrorStringConfirmed[i]:=FALSE;
				END_FOR
				iStepNumber:=0;
			END_CASE
	ELSE
			sStationERROR:='';
	END_IF
END_IF

