FUNCTION_BLOCK FB_ERROR_Handling_For_Station
// Összeszedi az állomáson belüli eszközök hibáit és egy string + 1 Bool-t ad ki magából
// Több hiba esetén kirakja a stringet és a bool-t, majd megvárja hogy a cella hibakezelő
// feldolgozza és csak utána rakja ki az új hibát

VAR_INPUT
		bEnable					:BOOL;
		arrsErrorString			:ARRAY[0..40]OF STRING[255];
		arrbError				:ARRAY[0..40]OF BOOL;
		arrERRORLevel			:ARRAY[0..40]OF USINT;			// Minden hibajelző eszköz beállítja 1-5-ig a hiba súlyosságát
		arrOEEErrorCode			:ARRAY[0..40]OF INT;
		iStationNumber			:UINT;
END_VAR
VAR_OUTPUT
		sStationERROR				:STRING[255];
		arrbErrorStringConfirmed	:ARRAY[0..40]OF BOOL;
END_VAR

VAR
	i							: INT;
	iAmountOfERROR				: INT;
	arrsErrorStringArchive		: ARRAY[0..40]OF STRING[255];
	arrsCLRErrorStringArchive	: ARRAY[0..40]OF STRING[255];
	r_TrigResetERROR			: R_TRIG;
	sErrorString				:STRING;


	iStepNumber					: INT;
	tofWaitAfterResetERROR		: TOF;
END_VAR

