FUNCTION_BLOCK FB_Warning_Handling_For_Stations
// Összeszedi az állomáson belüli eszközök figyelmeztetéseit és egy string + 1 Bool-t ad ki magából
// Több figyelmeztetés esetén mindíg kirakja a stringet és a bool-t, majd megvárja hogy a cella figyelmeztetéskezelő
// feldolgozza és csak utána rakja ki az új figyelmeztetést

VAR_INPUT
		bEnable							:BOOL;
		arrsWarningString				:ARRAY[0..20]OF STRING[250];
		arrbWarning						:ARRAY[0..20]OF BOOL;
		iStationNumber					:INT;
END_VAR
VAR_OUTPUT
		bStation_WARNING				:BOOL;
		sStationWarning					:STRING;
		arrbWarningConfirmed			:ARRAY[0..20]OF BOOL;
END_VAR
VAR
	i								: INT;
	iAmountOfWarning				: INT;
	arrsWarningStringArchive		: ARRAY[0..20]OF STRING(250);
	arrsCLRWarningStringArchive		: ARRAY[0..20]OF STRING(250);
	arr_WarningMessagesClr			:ARRAY[0..20] OF STRING[250];
	r_TrigResetWarning				: R_TRIG;

	iStepNumber: INT;
	tofWaitAfterResetWarning: TOF;
	btest: BOOL;
END_VAR

ST.xhtml:
arrbWarning[0];arrbWarning[1];
arrbWarning[2];arrbWarning[3];
arrbWarning[4];arrbWarning[5];
arrbWarning[6];arrbWarning[7];
arrbWarning[8];arrbWarning[9];
arrbWarning[10];arrbWarning[11];
arrbWarning[12];arrbWarning[13];
arrbWarning[14];arrbWarning[15];
arrbWarning[16];arrbWarning[17];
arrbWarning[18];arrbWarning[19];
arrbWarning[20];

arrsWarningString[0];arrsWarningString[1];
arrsWarningString[2];arrsWarningString[3];
arrsWarningString[4];arrsWarningString[5];
arrsWarningString[6];arrsWarningString[7];
arrsWarningString[8];arrsWarningString[9];
arrsWarningString[10];arrsWarningString[11];
arrsWarningString[12];arrsWarningString[13];
arrsWarningString[14];arrsWarningString[15];
arrsWarningString[16];arrsWarningString[17];
arrsWarningString[18];arrsWarningString[19];
arrsWarningString[20];

// Timers
tofWaitAfterResetWarning(IN:= , PT:=T#500MS , Q=> , ET=> );
tofWaitAfterResetWarning.ET;
IF bEnable	THEN
		// Get WARNNG bit from every device within the station
		IF NOT tofWaitAfterResetWarning.Q THEN							// Wait x ms after reset WARNNG, to give time to stations to reset their WARNING
			IF NOT  arr_StationData[iStationNumber].bStation_WARNING THEN
				FOR i:=0 TO 20 BY 1 DO
					IF arrbWarning[i] = TRUE THEN
						iAmountOfWarning:=iAmountOfWarning+1;
						IF iAmountOfWarning > 100 THEN
							iAmountOfWarning:=100;
						END_IF
					END_IF
				END_FOR
			END_IF
		ELSE
			tofWaitAfterResetWarning.IN:=FALSE;
		END_IF
		// Set Station WARNNG Bit
		IF iAmountOfWarning > 0 THEN
			 arr_StationData[iStationNumber].bStation_WARNING:=TRUE;
		END_IF

		// Reset WARNNG
		r_TrigResetWarning(CLK:=bGlobalResetWARNING , Q=> );

		IF r_TrigResetWarning.Q THEN
			iAmountOfWarning:=0;
			arr_StationData[iStationNumber].bStation_WARNING:=FALSE;
			arr_StationData[iStationNumber].sStation_WARNING:='';
			sStationWarning:='';
			arrsWarningStringArchive:=arrsCLRWarningStringArchive;
			arrsWarningString:=arr_WarningMessagesClr;
			iStepNumber:=0;
			tofWaitAfterResetWarning.IN:=TRUE;	
			btest:=TRUE;
		END_IF

		// WARNNG String handling
		CASE iStepNumber OF 
			0:// Chek if there is a new WARNNG String
			FOR i:=0 TO 20 DO
				IF arrsWarningString[i] <> arrsWarningStringArchive[i] 
					AND arrsWarningString[i]<> '' THEN
					 arrsWarningStringArchive[i]:= arrsWarningString[i];
					 arrbWarningConfirmed[i]:=TRUE;
					 arr_StationData[iStationNumber].sStation_WARNING:=CONCAT( arr_StationData[iStationNumber].sStationName,Concat('  :',arrsWarningString[i]));
					 sStationWarning:=CONCAT( arr_StationData[iStationNumber].sStationName,Concat('  :',arrsWarningString[i]));
					 iStepNumber:=10;
					 EXIT;
				END_IF
			END_FOR
			10:// Wait for Warning String confirmation from MAIN cycle

			IF arr_StationData[iStationNumber].bWarningStringConfirmed THEN			// Megvárja amíg a main ciklus kiírja a hibát, és csak utánna rak ki újat
				arr_StationData[iStationNumber].bWarningStringConfirmed:=FALSE;
				arr_StationData[iStationNumber].sStation_WARNING:='';
				iStepNumber:=0;
			END_IF

		END_CASE

		arr_StationData[iStationNumber].sStation_WARNING;
END_IF

