FUNCTION_BLOCK FB_StepChainSemafor_For_Stations
VAR_INPUT
	iStationNumber				:UINT;   // Constant
	iStepChainNumber			:INT;	// Constant		
	tStepOverTime				:TIME:=T#500MS;		
	bBypass_Automatic			:BOOL;	// If stepChain is independent from automatic mode
END_VAR
VAR_OUTPUT

END_VAR
VAR
	iStepNumberArchive			:INT;
	bStartTimer					:BOOL;
	ton_Step_Over_Time			:TON;
	rtrig_StepOver				:R_TRIG;	
	iTest: INT;
END_VAR

FUNCTION_BLOCK FB_StepChainSemafor_For_Stations
VAR_INPUT
	iStationNumber				:UINT;   // Constant
	iStepChainNumber			:INT;	// Constant		
	tStepOverTime				:TIME:=T#500MS;		
	bBypass_Automatic			:BOOL;	// If stepChain is independent from automatic mode
END_VAR
VAR_OUTPUT

END_VAR
VAR
	iStepNumberArchive			:INT;
	bStartTimer					:BOOL;
	ton_Step_Over_Time			:TON;
	rtrig_StepOver				:R_TRIG;	
	iTest: INT;
END_VAR

ST.xhtml:
//******************************************************** Watch over if step number has changed

IF arr_StationData[iStationNumber].arr_iStep[iStepChainNumber] <> iStepNumberArchive THEN
    iStepNumberArchive := arr_StationData[iStationNumber].arr_iStep[iStepChainNumber];
   	 arr_StationData[iStationNumber].arr_bSemafor[iStepChainNumber] := TRUE;
END_IF;

//********************************************************* Automatic reset of semafor
ton_Step_Over_Time(IN:=,
                    PT:=tStepOverTime);


// Start timer
IF NOT arr_StationData[iStationNumber].arr_bStepModeActive[iStepChainNumber]
    AND  arr_StationData[iStationNumber].arr_bSemafor[iStepChainNumber]
    AND (bAutomatic
    		OR bBypass_Automatic
			OR bBaseMoveActive) THEN
    	ton_Step_Over_Time.IN := TRUE;
END_IF;

ton_Step_Over_Time.ET;
IF ton_Step_Over_Time.Q THEN
     arr_StationData[iStationNumber].arr_bSemafor[iStepChainNumber] := FALSE;
	 ton_Step_Over_Time.IN:=FALSE;
	 iTest:=iTest+1;
END_IF;

//********************************************************* StepMode Active
rtrig_StepOver(CLK:=arr_StationData[iStationNumber].arr_bStepOver[iStepChainNumber]);



IF arr_StationData[iStationNumber].arr_bStepModeActive[iStepChainNumber]
    AND  arr_StationData[iStationNumber].arr_bSemafor[iStepChainNumber]
    AND rtrig_StepOver.Q THEN
    	 arr_StationData[iStationNumber].arr_bSemafor[iStepChainNumber] := FALSE;
END_IF;

