FUNCTION_BLOCK FB_StepTimeOUT_For_Stations
VAR_INPUT
	iStationNumber				:UINT;   // Constant
	iStepChainNumber			:UINT;	// Constant		
	tTimeOut					:TIME:=	T#5S;		
	bEnable						:BOOL;		
	sSequenceName				:STRING;
END_VAR
VAR_OUTPUT	
END_VAR
VAR
	iStepArchive				:UINT;		
	bStartTimer					:BOOL;		
	i							:UINT;		
	bException					:BOOL;			
	tonTimeOut					:TON;
	sStepTimeOutERROR_Temp		:STRING[255];;
END_VAR

FUNCTION_BLOCK FB_StepTimeOUT_For_Stations
VAR_INPUT
	iStationNumber				:UINT;   // Constant
	iStepChainNumber			:UINT;	// Constant		
	tTimeOut					:TIME:=	T#5S;		
	bEnable						:BOOL;		
	sSequenceName				:STRING;
END_VAR
VAR_OUTPUT	
END_VAR
VAR
	iStepArchive				:UINT;		
	bStartTimer					:BOOL;		
	i							:UINT;		
	bException					:BOOL;			
	tonTimeOut					:TON;
	sStepTimeOutERROR_Temp		:STRING[255];;
END_VAR

ST.xhtml:
IF tTimeOut = T#0S THEN
	tTimeOut:=T#5S;
END_IF


IF bEnable THEN

    IF NOT  arr_StationData[iStationNumber].arr_bStepTimeOutERROR[iStepChainNumber] THEN
        // Exception?
        bException := FALSE;
        i := 0;
        FOR i := 0 TO 20 DO
            IF arr_StationData[iStationNumber].arr_Exceptions[iStepChainNumber].arrExceptions[i] = arr_StationData[iStationNumber].arr_iStep[iStepChainNumber] THEN // ha tömb egyetlen eleme megegyezik az aktuális lépéssel akkor az kivétel
                bException := TRUE;
            END_IF;
        END_FOR;


        // NEW Step???
        IF arr_StationData[iStationNumber].arr_iStep[iStepChainNumber] <> iStepArchive THEN
            iStepArchive := arr_StationData[iStationNumber].arr_iStep[iStepChainNumber];
            bStartTimer := FALSE;
        ELSIF NOT bException THEN
            bStartTimer := TRUE;
        END_IF;

    END_IF;

    // Start TimeOut
    tonTimeOut(IN := bStartTimer,
                    PT :=tTimeOut);

    //TimeOut ERROR
    IF tonTimeOut.Q THEN
        arr_StationData[iStationNumber].arr_bStepTimeOutERROR[iStepChainNumber] := TRUE;
        sStepTimeOutERROR_Temp := CONCAT(sSequenceName,CONCAT(FC_Locale('',' Lepeslanc idotullepes: ','Step sequence time out: '), (arr_StationData[iStationNumber].arr_StepStatus[iStepChainNumber])));
        arr_StationData[iStationNumber].arr_sStepTimeOutERROR[iStepChainNumber] := CONCAT(sStepTimeOutERROR_Temp,CONCAT('  STEP: ' ,(INT_TO_STRING(arr_StationData[iStationNumber].arr_iStep[iStepChainNumber]))));
        bStartTimer := FALSE;
    END_IF;
END_IF;
  // RESET ERROR
IF bGlobalResetERROR
    OR NOT bEnable THEN
    arr_StationData[iStationNumber].arr_bStepTimeOutERROR[iStepChainNumber] := FALSE;
      arr_StationData[iStationNumber].arr_sStepTimeOutERROR[iStepChainNumber] := '';
    iStepArchive := 0;
END_IF;

arr_StationData[iStationNumber].arr_bStepTimeOutERROR[iStepChainNumber];
arr_StationData[iStationNumber].arr_sStepTimeOutERROR[iStepChainNumber];
arr_StationData[iStationNumber].arr_Exceptions[iStepChainNumber].arrExceptions[0];
arr_StationData[iStationNumber].arr_Exceptions[iStepChainNumber].arrExceptions[1];
arr_StationData[iStationNumber].arr_Exceptions[iStepChainNumber].arrExceptions[2];
arr_StationData[iStationNumber].arr_Exceptions[iStepChainNumber].arrExceptions[3];
arr_StationData[iStationNumber].arr_Exceptions[iStepChainNumber].arrExceptions[4];
arr_StationData[iStationNumber].arr_Exceptions[iStepChainNumber].arrExceptions[5];
arr_StationData[iStationNumber].arr_Exceptions[iStepChainNumber].arrExceptions[6];
arr_StationData[iStationNumber].arr_Exceptions[iStepChainNumber].arrExceptions[7];
arr_StationData[iStationNumber].arr_Exceptions[iStepChainNumber].arrExceptions[8];
arr_StationData[iStationNumber].arr_Exceptions[iStepChainNumber].arrExceptions[9];
arr_StationData[iStationNumber].arr_Exceptions[iStepChainNumber].arrExceptions[10];
arr_StationData[iStationNumber].arr_Exceptions[iStepChainNumber].arrExceptions[11];
arr_StationData[iStationNumber].arr_Exceptions[iStepChainNumber].arrExceptions[12];
arr_StationData[iStationNumber].arr_Exceptions[iStepChainNumber].arrExceptions[13];
arr_StationData[iStationNumber].arr_Exceptions[iStepChainNumber].arrExceptions[14];
arr_StationData[iStationNumber].arr_Exceptions[iStepChainNumber].arrExceptions[15];
arr_StationData[iStationNumber].arr_Exceptions[iStepChainNumber].arrExceptions[16];
arr_StationData[iStationNumber].arr_Exceptions[iStepChainNumber].arrExceptions[17];
arr_StationData[iStationNumber].arr_Exceptions[iStepChainNumber].arrExceptions[18];
arr_StationData[iStationNumber].arr_Exceptions[iStepChainNumber].arrExceptions[19];
arr_StationData[iStationNumber].arr_Exceptions[iStepChainNumber].arrExceptions[20];

